function OverseaClubBossRecordDialogCell:Awake()
    if self.BtnCheck then
        SetButtonAction(self.BtnCheck.gameObject,Bind(self,self.OnBtnCheckClick))
    end
end

function OverseaClubBossRecordDialogCell:RefreshShow(data)
    self.data = data
    CfUtils.FillText(self.PlayerName,self.data.playerName)
    local level = self.data.playerLevel or 10
    CfUtils.FillText(self.PlayerLevel,table.concat({"Lv.",level}))
    CfUtils.FillText(self.DamageNum,self.data.hurt)
    CfUtils.FillText(self.EndTime,CfUtils.GetTimeDYDHMS(self.data.createTime))
    CfUtils.FillText(self.Count,self.data.round)

    self:FillCommonHeadNode()
end

function OverseaClubBossRecordDialogCell:FillCommonHeadNode()
    local scr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
    if isNotNull(scr) then
        scr:FreshAvatarFrame(self.data.avatar, self.data.avatarFrame)
    end
end

function OverseaClubBossRecordDialogCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function OverseaClubBossRecordDialogCell:OnBtnCheckClick()
    local excludeDialogs = {
        { id = Constants.UITypeIds.UIClubBossChallengeDialog },
    }
    GameUtils.ShowCommonTeamsTipsBoard(self.BtnCheck.gameObject, self.data.team, '', self.data.questId, self.data.playerName, excludeDialogs)
end

